package actions

import (
	"context"
	"fmt"

	"github.com/google/go-github/v69/github"
	"github.com/mudler/LocalAGI/core/types"
	"github.com/mudler/LocalAGI/pkg/config"
	"github.com/sashabaranov/go-openai/jsonschema"
)

type GithubRepositoryREADME struct {
	token, customActionName string
	client                  *github.Client
}

func NewGithubRepositoryREADME(config map[string]string) *GithubRepositoryREADME {
	client := github.NewClient(nil).WithAuthToken(config["token"])

	return &GithubRepositoryREADME{
		client:           client,
		token:            config["token"],
		customActionName: config["customActionName"],
	}
}

func (g *GithubRepositoryREADME) Run(ctx context.Context, sharedState *types.AgentSharedState, params types.ActionParams) (types.ActionResult, error) {
	result := struct {
		Repository string `json:"repository"`
		Owner      string `json:"owner"`
	}{}
	err := params.Unmarshal(&result)
	if err != nil {
		fmt.Printf("error: %v", err)

		return types.ActionResult{}, err
	}
	fileContent, _, err := g.client.Repositories.GetReadme(ctx, result.Owner, result.Repository, &github.RepositoryContentGetOptions{})
	if err != nil {
		resultString := fmt.Sprintf("Error getting content : %v", err)
		return types.ActionResult{Result: resultString}, err
	}

	content, err := fileContent.GetContent()
	if err != nil {
		return types.ActionResult{}, err
	}

	return types.ActionResult{Result: content}, err
}

func (g *GithubRepositoryREADME) Definition() types.ActionDefinition {
	actionName := "github_readme"
	actionDescription := "Get the README file of a GitHub repository to have a basic understanding of the project."
	if g.customActionName != "" {
		actionName = g.customActionName
	}
	return types.ActionDefinition{
		Name:        types.ActionDefinitionName(actionName),
		Description: actionDescription,
		Properties: map[string]jsonschema.Definition{
			"repository": {
				Type:        jsonschema.String,
				Description: "The repository to search in",
			},
			"owner": {
				Type:        jsonschema.String,
				Description: "The owner of the repository",
			},
		},
		Required: []string{"repository", "owner"},
	}
}

func (a *GithubRepositoryREADME) Plannable() bool {
	return true
}

// GithubRepositoryREADMEConfigMeta returns the metadata for GitHub Repository README action configuration fields
func GithubRepositoryREADMEConfigMeta() []config.Field {
	return []config.Field{
		{
			Name:     "token",
			Label:    "GitHub Token",
			Type:     config.FieldTypeText,
			Required: true,
			HelpText: "GitHub API token with repository access",
		},
		{
			Name:     "customActionName",
			Label:    "Custom Action Name",
			Type:     config.FieldTypeText,
			HelpText: "Custom name for this action",
		},
	}
}

package agent

import (
	"encoding/json"
	"os"
	"strings"

	"github.com/mudler/LocalAGI/core/action"
	"github.com/mudler/LocalAGI/core/types"
	"golang.org/x/exp/slices"

	"github.com/mudler/xlog"

	"github.com/sashabaranov/go-openai"
)

type Messages []openai.ChatCompletionMessage

func (m Messages) ToOpenAI() []openai.ChatCompletionMessage {
	return []openai.ChatCompletionMessage(m)
}

func (m Messages) RemoveIf(f func(msg openai.ChatCompletionMessage) bool) Messages {
	for i := len(m) - 1; i >= 0; i-- {
		if f(m[i]) {
			m = append(m[:i], m[i+1:]...)
		}
	}
	return m
}

func (m Messages) String() string {
	s := ""
	for _, cc := range m {
		s += cc.Role + ": " + cc.Content + "\n"
	}
	return s
}

func (m Messages) Exist(content string) bool {
	for _, cc := range m {
		if cc.Content == content {
			return true
		}
	}
	return false
}

func (m Messages) RemoveLastUserMessage() Messages {
	if len(m) == 0 {
		return m
	}

	for i := len(m) - 1; i >= 0; i-- {
		if m[i].Role == UserRole {
			return append(m[:i], m[i+1:]...)
		}
	}

	return m
}

func (m Messages) Save(path string) error {
	content, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return err
	}

	f, err := os.Create(path)
	if err != nil {
		return err
	}

	defer f.Close()

	if _, err := f.Write(content); err != nil {
		return err
	}

	return nil
}

func (m Messages) GetLatestUserMessage() *openai.ChatCompletionMessage {
	xlog.Debug("Getting latest user message", "messages", m)
	for i := len(m) - 1; i >= 0; i-- {
		msg := m[i]
		if msg.Role == UserRole {
			return &msg
		}
	}

	return nil
}

// mergeLeadingSystemMessages replaces all leading system messages with a single
// system message. prefixBlocks are prepended in order (e.g. self-eval, then HUD).
// Only non-empty prefixBlocks are joined. Mid-conversation system messages are unchanged.
func (conv Messages) mergeLeadingSystemMessages(prefixBlocks ...string) Messages {
	var leading []string
	for _, s := range prefixBlocks {
		if s != "" {
			leading = append(leading, s)
		}
	}
	i := 0
	for i < len(conv) && conv[i].Role == SystemRole {
		content := conv[i].Content
		if content == "" && conv[i].MultiContent != nil {
			for _, part := range conv[i].MultiContent {
				if part.Type == openai.ChatMessagePartTypeText && part.Text != "" {
					content = part.Text
					break
				}
			}
		}
		if content != "" {
			leading = append(leading, content)
		}
		i++
	}
	if len(leading) == 0 {
		return conv
	}
	combined := strings.Join(leading, "\n\n")
	single := openai.ChatCompletionMessage{
		Role:    SystemRole,
		Content: combined,
	}
	return append([]openai.ChatCompletionMessage{single}, conv[i:]...)
}

// getAvailableActionsForJob returns available actions including user-defined ones for a specific job
func (a *Agent) getAvailableActionsForJob(job *types.Job) types.Actions {
	// Start with regular available actions
	baseActions := a.availableActions(job)

	// Add user-defined actions from the job
	userTools := job.GetUserTools()
	if len(userTools) > 0 {
		userDefinedActions := types.CreateUserDefinedActions(userTools)
		baseActions = append(baseActions, userDefinedActions...)
		xlog.Debug("Added user-defined actions", "definitions", userTools)
	}

	return baseActions
}

// availableActions returns the agent's own actions for a job, narrowed by the
// per-agent tool allow/deny-list. Doing it here keeps the HUD, the builtin-tool
// check and the tools handed to the model in agreement.
func (a *Agent) availableActions(j *types.Job) types.Actions {
	return a.options.toolFilter.filterActions(a.unfilteredActions(j))
}

func (a *Agent) unfilteredActions(j *types.Job) types.Actions {
	//	defaultActions := append(a.options.userActions, action.NewReply())

	defaultActions := slices.Clone(a.options.userActions)
	if j.Metadata["type"] == "scheduled" || (a.options.initiateConversations && a.selfEvaluationInProgress) { // && self-evaluation..
		acts := append(defaultActions, action.NewConversation())
		if a.options.enableHUD {
			acts = append(acts, action.NewState())
		}
		//if a.options.canStopItself {
		//		acts = append(acts, action.NewStop())
		//	}

		return acts
	}

	if a.options.canStopItself {
		acts := append(defaultActions, action.NewStop())
		if a.options.enableHUD {
			acts = append(acts, action.NewState())
		}
		return acts
	}

	if a.options.enableHUD {
		return append(defaultActions, action.NewState())
	}

	return defaultActions
}

func (a *Agent) prepareHUD() (promptHUD *PromptHUD) {
	if !a.options.enableHUD {
		return nil
	}

	return &PromptHUD{
		Character:     a.Character,
		CurrentState:  *a.currentState,
		PermanentGoal: a.options.permanentGoal,
		ShowCharacter: a.options.showCharacter,
	}
}

package actions

import (
	"context"
	"fmt"
	"slices"
	"strings"

	"github.com/mudler/LocalAGI/core/state"
	"github.com/mudler/LocalAGI/core/types"
	"github.com/mudler/LocalAGI/pkg/config"
	"github.com/sashabaranov/go-openai"
	"github.com/sashabaranov/go-openai/jsonschema"
)

func trimList(list []string) []string {
	for i, v := range list {
		list[i] = strings.TrimSpace(v)
	}
	return list
}

func NewCallAgent(config map[string]string, agentName string, pool *state.AgentPoolInternalAPI) *CallAgentAction {
	whitelist := []string{}
	blacklist := []string{}
	if v, ok := config["whitelist"]; ok {
		if strings.Contains(v, ",") {
			whitelist = trimList(strings.Split(v, ","))
		} else {
			whitelist = []string{v}
		}
	}
	if v, ok := config["blacklist"]; ok {
		if strings.Contains(v, ",") {
			blacklist = trimList(strings.Split(v, ","))
		} else {
			blacklist = []string{v}
		}
	}
	return &CallAgentAction{
		pool:      pool,
		myName:    agentName,
		whitelist: whitelist,
		blacklist: blacklist,
	}
}

type CallAgentAction struct {
	pool      *state.AgentPoolInternalAPI
	myName    string
	whitelist []string
	blacklist []string
}

func (a *CallAgentAction) Run(ctx context.Context, sharedState *types.AgentSharedState, params types.ActionParams) (types.ActionResult, error) {
	result := struct {
		AgentName string `json:"agent_name"`
		Message   string `json:"message"`
	}{}
	err := params.Unmarshal(&result)
	if err != nil {
		fmt.Printf("error: %v", err)

		return types.ActionResult{}, err
	}

	ag := a.pool.GetAgent(result.AgentName)
	if ag == nil {
		return types.ActionResult{}, fmt.Errorf("agent '%s' not found", result.AgentName)
	}

	resp := ag.Ask(
		types.WithConversationHistory(
			[]openai.ChatCompletionMessage{
				{
					Role:    "user",
					Content: result.Message,
				},
			},
		),
	)
	if resp.Error != nil {
		return types.ActionResult{}, err
	}

	metadata := make(map[string]interface{})

	for _, s := range resp.State {
		for k, v := range s.Metadata {
			if existingValue, ok := metadata[k]; ok {
				switch existingValue := existingValue.(type) {
				case []string:
					switch v := v.(type) {
					case []string:
						metadata[k] = append(existingValue, v...)
					case string:
						metadata[k] = append(existingValue, v)
					}
				case string:
					switch v := v.(type) {
					case []string:
						metadata[k] = append([]string{existingValue}, v...)
					case string:
						metadata[k] = []string{existingValue, v}
					}
				}
			} else {
				metadata[k] = v
			}
		}
	}

	return types.ActionResult{Result: resp.Response, Metadata: metadata}, nil
}

func (a *CallAgentAction) isAllowedToBeCalled(agentName string) bool {
	if agentName == a.myName {
		return false
	}

	if len(a.whitelist) > 0 && len(a.blacklist) > 0 {
		return slices.Contains(a.whitelist, agentName) && !slices.Contains(a.blacklist, agentName)
	}

	if len(a.whitelist) > 0 {
		return slices.Contains(a.whitelist, agentName)
	}

	if len(a.blacklist) > 0 {
		return !slices.Contains(a.blacklist, agentName)
	}
	return true
}

func (a *CallAgentAction) Definition() types.ActionDefinition {
	allAgents := a.pool.AllAgents()

	agents := []string{}

	for _, ag := range allAgents {
		if a.isAllowedToBeCalled(ag) {
			agents = append(agents, ag)
		}
	}

	description := "Use this tool to call another agent. Available agents and their roles are:"

	for _, agent := range agents {
		agentConfig := a.pool.GetConfig(agent)
		if agentConfig == nil {
			continue
		}
		description += fmt.Sprintf("\n\t- %s: %s", agent, agentConfig.Description)
	}

	return types.ActionDefinition{
		Name:        "call_agent",
		Description: description,
		Properties: map[string]jsonschema.Definition{
			"agent_name": {
				Type:        jsonschema.String,
				Description: "The name of the agent to call.",
				Enum:        agents,
			},
			"message": {
				Type:        jsonschema.String,
				Description: "The message to send to the agent.",
			},
		},
		Required: []string{"agent_name", "message"},
	}
}

func (a *CallAgentAction) Plannable() bool {
	return true
}

func CallAgentConfigMeta() []config.Field {
	return []config.Field{
		{
			Name:     "whitelist",
			Label:    "Whitelist",
			Type:     config.FieldTypeText,
			Required: false,
			HelpText: "Comma-separated list of agent names to call. If not specified, all agents are allowed.",
		},
		{
			Name:     "blacklist",
			Label:    "Blacklist",
			Type:     config.FieldTypeText,
			HelpText: "Comma-separated list of agent names to exclude from the call. If not specified, all agents are allowed.",
		},
	}
}

package actions

import (
	"context"
	"fmt"
	"log/slog"
	"strings"

	"github.com/mudler/LocalAGI/core/types"
	"github.com/mudler/LocalAGI/pkg/config"
	"github.com/sashabaranov/go-openai/jsonschema"
	"github.com/tmc/langchaingo/tools/duckduckgo"
	"mvdan.cc/xurls/v2"
)

const (
	MetadataUrls = "urls"
)

func NewSearch(config map[string]string) *SearchAction {
	results := config["results"]
	intResult := 1

	// decode int from string
	if results != "" {
		_, err := fmt.Sscanf(results, "%d", &intResult)
		if err != nil {
			fmt.Printf("error: %v", err)
		}
	}

	slog.Info("Search action with results: ", "results", intResult)
	return &SearchAction{results: intResult}
}

type SearchAction struct{ results int }

func (a *SearchAction) Run(ctx context.Context, sharedState *types.AgentSharedState, params types.ActionParams) (types.ActionResult, error) {
	result := struct {
		Query string `json:"query"`
	}{}
	err := params.Unmarshal(&result)
	if err != nil {
		fmt.Printf("error: %v", err)

		return types.ActionResult{}, err
	}
	ddg, err := duckduckgo.New(a.results, "LocalAGI")
	if err != nil {
		fmt.Printf("error: %v", err)

		return types.ActionResult{}, err
	}
	res, err := ddg.Call(ctx, result.Query)
	if err != nil {
		fmt.Printf("error: %v", err)

		return types.ActionResult{}, err
	}

	rxStrict := xurls.Strict()
	urls := rxStrict.FindAllString(res, -1)

	results := []string{}
	for _, u := range urls {
		// remove //duckduckgo.com/l/?uddg= from the url
		u = strings.ReplaceAll(u, "//duckduckgo.com/l/?uddg=", "")
		// remove everything with &rut=.... at the end
		u = strings.Split(u, "&rut=")[0]
		results = append(results, u)
	}

	return types.ActionResult{Result: res, Metadata: map[string]interface{}{MetadataUrls: results}}, nil
}

func (a *SearchAction) Definition() types.ActionDefinition {
	return types.ActionDefinition{
		Name:        "search_internet",
		Description: "Search the internet for something.",
		Properties: map[string]jsonschema.Definition{
			"query": {
				Type:        jsonschema.String,
				Description: "The query to search for.",
			},
		},
		Required: []string{"query"},
	}
}

func (a *SearchAction) Plannable() bool {
	return true
}

// SearchConfigMeta returns the metadata for Search action configuration fields
func SearchConfigMeta() []config.Field {
	return []config.Field{
		{
			Name:         "results",
			Label:        "Number of Results",
			Type:         config.FieldTypeNumber,
			DefaultValue: 1,
			Min:          1,
			Max:          100,
			Step:         1,
			HelpText:     "Number of search results to return",
		},
	}
}

package actions

import (
	"context"
	"fmt"

	"github.com/google/go-github/v69/github"
	"github.com/mudler/LocalAGI/core/types"
	"github.com/mudler/LocalAGI/pkg/config"
	"github.com/mudler/xlog"
	"github.com/sashabaranov/go-openai/jsonschema"
)

type GithubIssueSearch struct {
	token, repository, owner, customActionName string
	client                                     *github.Client
}

func NewGithubIssueSearch(config map[string]string) *GithubIssueSearch {
	client := github.NewClient(nil).WithAuthToken(config["token"])

	return &GithubIssueSearch{
		client:           client,
		token:            config["token"],
		repository:       config["repository"],
		owner:            config["owner"],
		customActionName: config["customActionName"],
	}
}

func (g *GithubIssueSearch) Run(ctx context.Context, sharedState *types.AgentSharedState, params types.ActionParams) (types.ActionResult, error) {
	result := struct {
		Query      string `json:"query"`
		Repository string `json:"repository"`
		Owner      string `json:"owner"`
	}{}
	err := params.Unmarshal(&result)
	if err != nil {
		fmt.Printf("error: %v", err)

		return types.ActionResult{}, err
	}

	if g.repository != "" && g.owner != "" {
		result.Repository = g.repository
		result.Owner = g.owner
	}

	query := fmt.Sprintf("%s in:%s user:%s", result.Query, result.Repository, result.Owner)
	resultString := ""
	issues, _, err := g.client.Search.Issues(ctx, query, &github.SearchOptions{
		ListOptions: github.ListOptions{PerPage: 5},
		Order:       "desc",
		//Sort:        "created",
	})
	if err != nil {
		resultString = fmt.Sprintf("Error listing issues: %v", err)
		return types.ActionResult{Result: resultString}, err
	}
	for _, i := range issues.Issues {
		xlog.Info("Issue found", "title", i.GetTitle())
		resultString += fmt.Sprintf("Issue found: %s\n", i.GetTitle())
		resultString += fmt.Sprintf("URL: %s\n", i.GetHTMLURL())
		//	resultString += fmt.Sprintf("Body: %s\n", i.GetBody())
	}

	return types.ActionResult{Result: resultString}, err
}

func (g *GithubIssueSearch) Definition() types.ActionDefinition {
	actionName := "search_github_issue"
	if g.customActionName != "" {
		actionName = g.customActionName
	}
	if g.repository != "" && g.owner != "" {
		return types.ActionDefinition{
			Name:        types.ActionDefinitionName(actionName),
			Description: "Search between github issues",
			Properties: map[string]jsonschema.Definition{
				"query": {
					Type:        jsonschema.String,
					Description: "The text to search for",
				},
			},
			Required: []string{"query"},
		}
	}
	return types.ActionDefinition{
		Name:        types.ActionDefinitionName(actionName),
		Description: "Search between github issues",
		Properties: map[string]jsonschema.Definition{
			"query": {
				Type:        jsonschema.String,
				Description: "The text to search for",
			},
			"repository": {
				Type:        jsonschema.String,
				Description: "The repository to search in",
			},
			"owner": {
				Type:        jsonschema.String,
				Description: "The owner of the repository",
			},
		},
		Required: []string{"query", "repository", "owner"},
	}
}

func (a *GithubIssueSearch) Plannable() bool {
	return true
}

// GithubIssueSearchConfigMeta returns the metadata for GitHub Issue Search action configuration fields
func GithubIssueSearchConfigMeta() []config.Field {
	return []config.Field{
		{
			Name:     "token",
			Label:    "GitHub Token",
			Type:     config.FieldTypeText,
			Required: true,
			HelpText: "GitHub API token with repository access",
		},
		{
			Name:     "repository",
			Label:    "Repository",
			Type:     config.FieldTypeText,
			Required: true,
			HelpText: "GitHub repository name",
		},
		{
			Name:     "owner",
			Label:    "Owner",
			Type:     config.FieldTypeText,
			Required: true,
			HelpText: "GitHub repository owner",
		},
		{
			Name:     "customActionName",
			Label:    "Custom Action Name",
			Type:     config.FieldTypeText,
			HelpText: "Custom name for this action",
		},
	}
}

package actions

import (
	"context"
	"fmt"
	"strings"

	"github.com/google/go-github/v69/github"
	"github.com/mudler/LocalAGI/core/types"
	"github.com/mudler/LocalAGI/pkg/config"
	"github.com/sashabaranov/go-openai/jsonschema"
)

type GithubRepositorySearchFiles struct {
	token, repository, owner, customActionName string
	client                                     *github.Client
}

func NewGithubRepositorySearchFiles(config map[string]string) *GithubRepositorySearchFiles {
	client := github.NewClient(nil).WithAuthToken(config["token"])

	return &GithubRepositorySearchFiles{
		client:           client,
		token:            config["token"],
		repository:       config["repository"],
		owner:            config["owner"],
		customActionName: config["customActionName"],
	}
}

func (g *GithubRepositorySearchFiles) searchFilesRecursively(ctx context.Context, path string, owner string, repository string, searchPattern string) (string, error) {
	var result strings.Builder

	// Get content at the current path
	_, directoryContent, _, err := g.client.Repositories.GetContents(ctx, owner, repository, path, nil)
	if err != nil {
		return "", fmt.Errorf("error getting content at path %s: %w", path, err)
	}

	// Process each item in the directory
	for _, item := range directoryContent {
		if item.GetType() == "dir" {
			// Recursively search in subdirectories
			subContent, err := g.searchFilesRecursively(ctx, item.GetPath(), owner, repository, searchPattern)
			if err != nil {
				return "", err
			}
			result.WriteString(subContent)
		} else if item.GetType() == "file" {
			// Check if file name matches the search pattern
			if strings.Contains(strings.ToLower(item.GetName()), strings.ToLower(searchPattern)) {
				// Get file content
				fileContent, _, _, err := g.client.Repositories.GetContents(ctx, owner, repository, item.GetPath(), nil)
				if err != nil {
					return "", fmt.Errorf("error getting file content for %s: %w", item.GetPath(), err)
				}

				content, err := fileContent.GetContent()
				if err != nil {
					return "", fmt.Errorf("error decoding content for %s: %w", item.GetPath(), err)
				}

				// Add file content to result with clear markers
				result.WriteString(fmt.Sprintf("\n--- START FILE: %s ---\n", item.GetPath()))
				result.WriteString(content)
				result.WriteString(fmt.Sprintf("\n--- END FILE: %s ---\n", item.GetPath()))
			}
		}
	}

	return result.String(), nil
}

func (g *GithubRepositorySearchFiles) Run(ctx context.Context, sharedState *types.AgentSharedState, params types.ActionParams) (types.ActionResult, error) {
	result := struct {
		Repository    string `json:"repository"`
		Owner         string `json:"owner"`
		Path          string `json:"path,omitempty"`
		SearchPattern string `json:"searchPattern"`
	}{}
	err := params.Unmarshal(&result)
	if err != nil {
		return types.ActionResult{}, fmt.Errorf("failed to unmarshal params: %w", err)
	}

	if g.repository != "" && g.owner != "" {
		result.Repository = g.repository
		result.Owner = g.owner
	}

	// Start from root if no path specified
	if result.Path == "" {
		result.Path = "."
	}

	content, err := g.searchFilesRecursively(ctx, result.Path, result.Owner, result.Repository, result.SearchPattern)
	if err != nil {
		return types.ActionResult{}, err
	}

	return types.ActionResult{Result: content}, nil
}

func (g *GithubRepositorySearchFiles) Definition() types.ActionDefinition {
	actionName := "search_github_repository_files"
	if g.customActionName != "" {
		actionName = g.customActionName
	}
	description := "Search for files in a GitHub repository and return their content"
	if g.repository != "" && g.owner != "" {
		return types.ActionDefinition{
			Name:        types.ActionDefinitionName(actionName),
			Description: description,
			Properties: map[string]jsonschema.Definition{
				"path": {
					Type:        jsonschema.String,
					Description: "Optional path to start searching from (defaults to repository root)",
				},
				"searchPattern": {
					Type:        jsonschema.String,
					Description: "Pattern to search for in file names (case-insensitive)",
				},
			},
			Required: []string{"searchPattern"},
		}
	}
	return types.ActionDefinition{
		Name:        types.ActionDefinitionName(actionName),
		Description: description,
		Properties: map[string]jsonschema.Definition{
			"path": {
				Type:        jsonschema.String,
				Description: "Optional path to start searching from (defaults to repository root)",
			},
			"repository": {
				Type:        jsonschema.String,
				Description: "The repository to search in",
			},
			"owner": {
				Type:        jsonschema.String,
				Description: "The owner of the repository",
			},
			"searchPattern": {
				Type:        jsonschema.String,
				Description: "Pattern to search for in file names (case-insensitive)",
			},
		},
		Required: []string{"repository", "owner", "searchPattern"},
	}
}

func (a *GithubRepositorySearchFiles) Plannable() bool {
	return true
}

