		aRemove *actions.RemoveFromMemoryAction
		aSearch *actions.SearchMemoryAction
	)

	BeforeEach(func() {
		var err error
		tmpDir, err = os.MkdirTemp("", "memory_test_*")
		Expect(err).ToNot(HaveOccurred())
		indexPath = filepath.Join(tmpDir, "memory.bleve")
